{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C45"],
      "claim": "Safinamide absolute oral bioavailability was 95% in healthy subjects after a 50 mg IR tablet versus IV, directly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C60"],
      "claim": "Betaxolol absolute bioavailability was 0.84 ± 0.07 after a 40 mg oral capsule versus IV in healthy male subjects, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Atenolol absolute bioavailability was 0.56 ± 0.17 for a 100 mg oral solution in normal subjects, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Sorafenib absolute oral bioavailability was 38–49% in patients at 400 mg twice daily, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Tocapinide oral bioavailability was essentially 100% in humans, strongly above the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C57"],
      "claim": "Posaconazole suspension absolute bioavailability was estimated at 16% (8–27%) in immunocompromised pediatric patients, a sub-20% value that introduces uncertainty.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most high-transfer experimental records report absolute oral bioavailability above 20%, often 50–95%, with only a population-specific posaconazole value below threshold. The query's glycoside-like polyol architecture is consistent with orally bioavailable C-aryl glucosides, so high is better supported.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule.",
    "No structurally close analogue with an absolute F value; high-transfer evidence comes from diverse chemotypes.",
    "Some drugs show population- and formulation-dependent F values, so threshold classification may be context-dependent."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

